+package com.example;
+
+import com.microsoft.playwright.Browser;
+import com.microsoft.playwright.BrowserType;
+import com.microsoft.playwright.Locator;
+import com.microsoft.playwright.Page;
+import com.microsoft.playwright.Playwright;
+import com.microsoft.playwright.options.AriaRole;
+import java.util.List;
+import java.util.Map;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+
+import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
+import static org.junit.jupiter.api.Assertions.assertEquals;
+
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT,
+        properties = "vaadin.launch-browser=false")
+class ContactBrowserTest {
+    @LocalServerPort
+    private int port;
+
+    @Test
+    void validatesSendsAndProtectsDraftsInChromium() {
+        try (Playwright playwright = Playwright.create(new Playwright.CreateOptions()
+                .setEnv(Map.of("PLAYWRIGHT_SKIP_BROWSER_DOWNLOAD", "1")));
+             Browser browser = playwright.chromium().launch(new BrowserType.LaunchOptions()
+                     .setHeadless(true).setArgs(List.of("--no-sandbox")))) {
+            Page page = browser.newPage();
+            page.navigate("http://localhost:" + port + "/contact");
+            Locator name = page.getByLabel("Name", new Page.GetByLabelOptions().setExact(true));
+            Locator email = page.getByLabel("Email", new Page.GetByLabelOptions().setExact(true));
+            Locator phone = page.getByLabel("Phone", new Page.GetByLabelOptions().setExact(true));
+            Locator message = page.getByLabel("Message", new Page.GetByLabelOptions().setExact(true));
+            Locator send = page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Send").setExact(true));
+            assertThat(send).isEnabled();
+            send.click();
+            assertThat(page.getByText("Name is required", new Page.GetByTextOptions().setExact(true))).isVisible();
+            assertThat(page.getByText("Give an e-mail address or a phone number", new Page.GetByTextOptions().setExact(true))).isVisible();
+            assertThat(page.getByText("Message is required", new Page.GetByTextOptions().setExact(true))).isVisible();
+
+            name.fill("Browser sender");
+            email.fill("broken");
+            message.fill("Browser message");
+            send.click();
+            assertThat(page.getByText("Enter a valid e-mail address", new Page.GetByTextOptions().setExact(true))).isVisible();
+            assertThat(message).hasValue("Browser message");
+            email.fill("browser@example.com");
+            email.press("Enter");
+            assertThat(send).isDisabled();
+            assertThat(page.getByText("Message sent", new Page.GetByTextOptions().setExact(true))).isVisible();
+            assertThat(name).hasValue("");
+            assertThat(email).hasValue("");
+            assertThat(phone).hasValue("");
+            assertThat(message).hasValue("");
+            assertThat(page.locator("vaadin-grid")).containsText("Browser message");
+
+            // This marker proves the RouterLink keeps the same browser document.
+            page.evaluate("window.contactDocumentMarker = 'same document'");
+            page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+            assertThat(page.getByRole(AriaRole.HEADING, new Page.GetByRoleOptions().setName("About"))).isVisible();
+            assertEquals("same document", page.evaluate("window.contactDocumentMarker"));
+            page.goBack();
+            assertThat(page.locator("vaadin-grid")).containsText("Browser message");
+            assertThat(send).isEnabled();
+            phone.fill("Draft phone");
+            page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+            page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Keep editing")).click();
+            assertThat(phone).hasValue("Draft phone");
+            page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+            page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Discard").setExact(true)).click();
+            assertThat(page.getByRole(AriaRole.HEADING, new Page.GetByRoleOptions().setName("About"))).isVisible();
+        }
+    }
+}
